package com.example.practice;

import java.io.IOException;

import org.jpos.iso.ISOException;
import org.jpos.iso.ISOMsg;
import org.jpos.iso.ISORequestListener;
import org.jpos.iso.ISOSource;
import org.jpos.util.Log;
import org.jpos.util.LogEvent;
import org.jpos.util.LogSource;
import org.jpos.util.Logger;

/**
 * Answers the echoes (0800) that the host sends on its own. It runs as a request listener on the
 * client's QMUX:
 *
 * <pre>
 *   &lt;request-listener class="com.example.practice.EchoResponder" logger="Q2" realm="echo-responder"/&gt;
 * </pre>
 *
 * Q2 creates one instance, calls {@link #setLogger} with the element's logger and realm, and hands
 * it every message from the host that no request was waiting for.
 */
public class EchoResponder implements ISORequestListener, LogSource {
    private Log log = new Log();

    @Override
    public boolean process(ISOSource source, ISOMsg m) {
        if (!"0800".equals(mtiOf(m)))
            return false;                       // not ours: the next listener, or <unhandled>
        answer(source, m);
        return true;
    }

    /** Answers one echo from the host. */
    void answer(ISOSource source, ISOMsg echo) {
        LogEvent ev = log.createInfo();
        ev.addMessage(echo);
        try {
            ISOMsg reply = reply(echo);
            source.send(reply);
            ev.addMessage(reply);
        } catch (IOException | ISOException e) {
            ev.setTag("warn");
            ev.addMessage(e);
        } finally {
            Logger.log(ev);
        }
    }

    @Override
    public void setLogger(Logger logger, String realm) {
        log = new Log(logger, realm);
    }

    @Override
    public String getRealm() {
        return log.getRealm();
    }

    @Override
    public Logger getLogger() {
        return log.getLogger();
    }

    /** Given: the 0810 that answers an echo. */
    static ISOMsg reply(ISOMsg echo) throws ISOException {
        ISOMsg r = (ISOMsg) echo.clone();
        r.setResponseMTI();
        r.set(39, "00");
        return r;
    }

    private static String mtiOf(ISOMsg m) {
        try {
            return m.getMTI();
        } catch (ISOException e) {
            return null;
        }
    }
}

import com.example.practice.EchoResponder;
import java.io.IOException;
import org.jpos.iso.ISOMsg;
import org.jpos.iso.ISOSource;
import org.jpos.util.SimpleLogListener;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        Logger root = Logger.getLogger("");
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            org.jpos.util.Logger node = new org.jpos.util.Logger();
            node.addListener(new SimpleLogListener(System.out));
            EchoResponder responder = new EchoResponder();
            responder.setLogger(node, "echo-responder");
            ISOMsg echo = new ISOMsg("0800");
            echo.set(7, "1114103000");
            echo.set(11, "120044");
            echo.set(70, "301");
            System.out.println("handled echo: " + responder.process(new Link(false), echo));
            echo.set(11, "120045");
            System.out.println("handled echo on a broken link: " + responder.process(new Link(true), echo));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    /** The host's side of the link: prints each reply, or fails to send. */
    private record Link(boolean broken) implements ISOSource {
        @Override public void send(ISOMsg m) throws IOException {
            if (broken) {
                IOException reset = new IOException("broken pipe");
                reset.setStackTrace(new StackTraceElement[0]);
                throw reset;
            }
            System.out.println("reply sent: " + m.getString(0) + " STAN " + m.getString(11) + " rc " + m.getString(39));
        }
        @Override public boolean isConnected() { return true; }
    }
}

